interactions.sample_code:
function partition(A, p, r) {
  let i = p - 1;
  set_i(i);
  for (let j = p; j < r; j++) {
    set_j(j);
    if (compare(j, r)) {
      i++;
      set_i(i);
      swap(i, j);
    }
  }
  swap(i + 1, r);
  set_i(i + 1);
  return i + 1;
}

